const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const volcanoPoint = ee.Geometry.Point([-19.62, 63.63]); // Eyjafjallajökull volcano
  const analysisDate = '2010-05-10';

  // Define two boxes of the same size, one north and one south of the volcano.
  // The plume traveled hundreds of kilometers, so these boxes capture a large area.
  // [lon_min, lat_min, lon_max, lat_max]
  const northBox = ee.Geometry.Rectangle([-25, 64, -15, 67]); // Box north of the volcano
  const southBox = ee.Geometry.Rectangle([-25, 60, -15, 63]); // Box south of the volcano

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('TOMS/Aura_OMI_Level3_OMSO2e')
    .filterDate(analysisDate, ee.Date(analysisDate).advance(1, 'day'));

  const imageCount = collection.size().getInfo();
  if (imageCount === 0) {
    console.log('No OMI SO2 image found for May 10, 2010.');
    console.log("C1");
    return;
  }

  const image = collection.first();
  const so2Band = image.select('SulfurDioxide_PBL_Volume_Mixing_Ratio_15km');

  // 3. Processing & Calculation
  // Calculate mean SO2 and pixel count for the northern region
  const northStats = so2Band.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: northBox,
    scale: 30000, // OMI resolution is coarse, use a large scale
    maxPixels: 1e9
  });

  // Calculate mean SO2 and pixel count for the southern region
  const southStats = so2Band.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: southBox,
    scale: 30000,
    maxPixels: 1e9
  });

  // Use getInfo() once to retrieve all stats
  const northResult = northStats.getInfo();
  const southResult = southStats.getInfo();

  const northMean = northResult['SulfurDioxide_PBL_Volume_Mixing_Ratio_15km_mean'];
  const northCount = northResult['SulfurDioxide_PBL_Volume_Mixing_Ratio_15km_count'];
  const southMean = southResult['SulfurDioxide_PBL_Volume_Mixing_Ratio_15km_mean'];
  const southCount = southResult['SulfurDioxide_PBL_Volume_Mixing_Ratio_15km_count'];

  // 4. Validation
  if (northCount === 0 || southCount === 0) {
    console.log(`North Pixel Count: ${northCount}`);
    console.log(`South Pixel Count: ${southCount}`);
    console.log('No valid pixels in one or both analysis regions.');
    console.log("C2");
    return;
  }

  if (northMean === null || southMean === null) {
      console.log(`North Mean SO2: ${northMean}`);
      console.log(`South Mean SO2: ${southMean}`);
      console.log('Calculation resulted in a null value.');
      console.log("C3");
      return;
  }

  // 5. Final Answer
  console.log(`Image found for ${analysisDate}: Yes (1 image)`);
  console.log(`Mean SO2 North (Dobson Units): ${northMean.toFixed(4)}`);
  console.log(`North Pixels: ${northCount}`);
  console.log(`Mean SO2 South (Dobson Units): ${southMean.toFixed(4)}`);
  console.log(`South Pixels: ${southCount}`);

  if (northMean > southMean) {
    console.log('Evidence: SO2 concentration is higher to the north.');
    console.log('A');
  } else {
    console.log('Evidence: SO2 concentration is not higher to the north.');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred:', err);
    console.log("D");
});
